import re
for i in range(2,14):
    inp=open(f'extracted/xl/worksheets/sheet{i}.xml').read()
    gol=open(f'golden_x/xl/worksheets/sheet{i}.xml').read()
    def cells(x):
        rows=re.findall(r'<row[^>]*>(.*?)</row>', x)
        out={}
        for ri,r in enumerate(rows,start=1):
            # split self-closing cells first
            for m in re.finditer(r'<c r=\"([A-Z]+[0-9]+)\"[^>]*/>', r):
                out[(ri,m.group(1))]=m.group(0)
            for m in re.finditer(r'<c r=\"([A-Z]+[0-9]+)\"[^>]*>.*?</c>', r):
                out[(ri,m.group(1))]=m.group(0)
        return out
    ci, cg = cells(inp), cells(gol)
    diffs=[k for k in sorted(set(ci)|set(cg)) if ci.get(k)!=cg.get(k)]
    print('sheet',i,'diffs',len(diffs))
    for k in diffs:
        print(k)
        print(' I:',ci.get(k)[:200])
        print(' G:',cg.get(k)[:200])
